function emptyState(){const zh={l2:['还没有新的 L2 时间线','完成 L1 蒸馏后，项目的发展过程会在这里形成可读时间线。'],l3:['还没有新的 L3 项目规则','L2 稳定后，这里会沉淀长期规则、偏好、经验与工作方式。'],l4:['还没有新的 L4 用户画像','至少多个项目形成 L3 后，才会生成跨项目稳定画像。'],skills:['还没有可复用 Skill','Skill 独立于 L1-L4，可由稳定流程和经验演化而来。'],processing:['当前没有蒸馏任务','新的 L1 证据达到阈值或空闲条件后会进入队列。']}[current]||['暂无数据','当前视图没有匹配内容。'];const en={l2:['No L2 timeline yet','Project chronology appears here after valid L1 distillation.'],l3:['No L3 project rules yet','Durable rules, preferences, experience, and working habits appear after L2 stabilizes.'],l4:['No L4 user profile yet','Cross-project traits require supported L3 evidence from multiple projects.'],skills:['No reusable Skills yet','Skills evolve independently from stable procedures and experience.'],processing:['No distillation jobs','New jobs appear when L1 evidence reaches the configured threshold or idle condition.']}[current]||['No data','There is no content matching this view.'];const copy=lang==='zh'?zh:en;return '<div class="empty-state"><span>'+esc(eyebrows[current]||'EMPTY')+'</span><h3>'+esc(copy[0])+'</h3><p>'+esc(copy[1])+'</p>'+(current!=='processing'?'<button class="soft" type="button" onclick="load(\\\'processing\\\')">'+(lang==='zh'?'查看处理队列':'Open processing')+'</button>':'')+'</div>'}
function renderProjects(items){const box=document.getElementById('items');box.className='items project-ledger';const sorted=[...items].sort((a,b)=>{const ap=(a.pending_todo_count||a.pending_todos?.length||0)>0?1:0,bp=(b.pending_todo_count||b.pending_todos?.length||0)>0?1:0;if(ap!==bp)return bp-ap;return String(b.updated_at||b.updatedAt||'').localeCompare(String(a.updated_at||a.updatedAt||''))});window.visibleItems=sorted;box.innerHTML=sorted.length?sorted.map((x,i)=>{const todos=Array.isArray(x.pending_todos)?x.pending_todos:[],id=x.project_id||x.id||'',summary=x.description||(lang==='zh'?'暂无项目描述；打开详情可查看注册信息与记忆范围。':'No project description; open details for registry and memory scope.');return '<button type="button" class="project-ledger-record" data-item-index="'+i+'" onclick="openItem('+i+')"><div class="project-ledger-identity"><div><h3>'+esc(x.title||x.name||id)+'</h3><span class="project-slug">'+esc(id)+'</span></div><div class="project-identity-meta"><span class="state-dot '+esc(statusOf(x)||'active')+'">'+esc(statusText(statusOf(x)||'active'))+'</span><time>'+esc(fmtTime(x.updated_at||x.updatedAt))+'</time></div></div><div class="project-ledger-overview"><span class="record-label">'+(lang==='zh'?'概览 / Current Truth':'Overview / Current Truth')+'</span><p>'+esc(summary)+'</p><small>'+(Array.isArray(x.aliases)&&x.aliases.length?(lang==='zh'?'别名：':'Aliases: ')+esc(x.aliases.slice(0,3).join(' · ')):(lang==='zh'?'无别名':'No aliases'))+'</small></div><div class="project-ledger-todos"><div><span class="record-label">TODO</span><b>'+esc(todos.length)+'</b></div><div class="project-todo-lines">'+(todos.length?todos.slice(0,2).map(t=>'<span class="todo-preview-line"><i aria-hidden="true"></i><span>'+esc(t.text)+'</span></span>').join(''):'<span class="muted">'+(lang==='zh'?'当前没有待办':'No pending todos')+'</span>')+'</div></div><i aria-hidden="true">→</i></button>'}).join(''):emptyState()}
function renderL1(items){const box=document.getElementById('items');box.className='items turn-list';window.visibleItems=items;box.innerHTML=items.length?items.map((x,i)=>{const core=x.source_kind==='memory-core',raw=x.source_kind==='raw-turn';const copy=core?'<p><strong>M</strong>'+esc(x.title||x.summary||'—')+'</p><p><strong>↳</strong>'+esc(x.summary||'—')+'</p>':raw?'<p><strong>U</strong>'+esc(x.userText||'—')+'</p><p><strong>A</strong>'+esc(x.assistantText||'—')+'</p>':'<p><strong>U</strong>'+esc(x.user_text||'—')+'</p><p><strong>A</strong>'+esc(x.assistant_text||'—')+'</p>';const label=core?'L1 · MEMORY':raw?'L1 · RAW TURN':'L1 · TURN';const project=x.project_unresolved?('unresolved · '+(x.raw_project_id||'workspace')):(x.project_hint||x.project_id||x.projectId||'—');return '<button type="button" class="turn-row" data-item-index="'+i+'" onclick="openItem('+i+')"><div class="turn-meta"><span>'+label+'</span><b>'+esc(statusText(statusOf(x)||'complete'))+'</b><time>'+esc(fmtTime(x.timestamp||x.updated_at||x.updatedAt||x.createdAt))+'</time></div><div class="turn-copy">'+copy+'</div><div class="turn-project">'+esc(project)+'</div></button>'}).join(''):emptyState()}
function memoryRowHtml(x,i,token=current.toUpperCase()){return '<button type="button" class="memory-row" data-item-index="'+i+'" onclick="openItem('+i+')"><span class="layer-token">'+esc(token)+'</span><div><div class="memory-row-head"><h3>'+esc(x.title||x.name||itemId(x)||'(untitled)')+'</h3><span>'+esc(statusOf(x)?statusText(statusOf(x)):'')+'</span></div><p>'+esc(textOf(x))+'</p><small>'+esc(projectOf(x)||x.updatedAt||x.updated_at||'')+'</small></div><i aria-hidden="true">→</i></button>'}
function renderSkills(items){const box=document.getElementById('items'),origin=x=>{const tags=Array.isArray(x?.tags)?x.tags:[];if(tags.includes('legacy-import')||tags.includes('agent-source'))return'external';if(tags.includes('distilled')||tags.some(t=>typeof t==='string'&&t.startsWith('distill-contract:')))return'governed';return'unknown'},groups=[['governed',lang==='zh'?'Memhub 治理 Skill':'Memhub governed Skills'],['external',lang==='zh'?'外部 Agent 同步 Skill':'External Agent Skills'],['unknown',lang==='zh'?'待确认来源':'Unknown provenance']].map(([key,label])=>({key,label,items:items.filter(x=>origin(x)===key)})).filter(group=>group.items.length);const ordered=groups.flatMap(group=>group.items);window.visibleItems=ordered;let offset=0;const renderGroup=group=>{const start=offset;offset+=group.items.length;const rows=group.items.map((x,i)=>memoryRowHtml(x,start+i,'SK')).join('');const head='<span>'+esc(group.label)+'</span><b>'+group.items.length+'</b>';return group.key==='governed'?'<section class="skill-group governed"><div class="skill-group-head">'+head+'</div>'+rows+'</section>':'<details class="skill-group '+group.key+'"><summary>'+head+'</summary>'+rows+'</details>'};box.className='items skill-list';box.innerHTML=groups.length?groups.map(renderGroup).join(''):emptyState()}
